import React, { useState, useEffect, useRef } from "react";
import {
  AppBar,
  Toolbar,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
  Box,
  useMediaQuery,
  useTheme,
  Tabs,
  Tab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  Rating,
  TextField,
  Button,
  Avatar,
  Chip,
  CircularProgress,
  Grid,
  ImageList,
  ImageListItem,
} from "@mui/material";
import { GiHamburgerMenu } from "react-icons/gi";
import { FaTableTennis, FaCloudUploadAlt } from "react-icons/fa";
import { Close, Delete } from "@mui/icons-material";
import CustomButton from "../Components/CustomButton";
import { GoogleLogin } from "@react-oauth/google";
import { jwtDecode } from "jwt-decode";
import colorLogo from "../Assets/color.png";

const NavBar = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [currentTab, setCurrentTab] = useState(0);
  const [reviewDialogOpen, setReviewDialogOpen] = useState(false);
  const [authDialogOpen, setAuthDialogOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [feedbackDialog, setFeedbackDialog] = useState({
    open: false,
    message: "",
    severity: "success",
  });
  const [hasReviewed, setHasReviewed] = useState(false);
  const [checkingReview, setCheckingReview] = useState(false);
  const [additionalPhotosUploading, setAdditionalPhotosUploading] =
    useState(false);
  const [googleAuthLoading, setGoogleAuthLoading] = useState(false);

  // Replace this with your actual Google Apps Script URL
  const GOOGLE_SCRIPT_URL =
    "https://script.google.com/macros/s/AKfycbxu79sYZb_yIEeM9pLZczPCAtw6AGCM0JpWYu2GuNWqyzTFh7FvwkmVG1SueS9JwC5lBA/exec";

  const [reviewData, setReviewData] = useState({
    name: "",
    rating: 0,
    comment: "",
  });

  const [addPhotos, setAddPhotos] = useState([]);
  const [addPhotosPreview, setAddPhotosPreview] = useState([]);
  const addPhotosInputRef = useRef();

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const menuItems = [
    { label: "Home", href: "#home" },
    { label: "About", href: "#about" },
    { label: "Testimonials", href: "#testimonials" },
    { label: "Gallery and Awards", href: "#gallery" },
  ];

  // File to base64 conversion
// File to base64 conversion - FIXED TYPO
const fileToBase64 = (file) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result.split(",")[1]); // Fixed: was " , " should be ","
    reader.onerror = (error) => reject(error);
  });

  const filesToBase64Array = async (files) =>
    Promise.all(
      files.map(async (file) => ({
        base64: await fileToBase64(file),
        name: file.name,
        type: file.type,
      }))
    );

  // Function to convert Google Drive URL to direct image URL
// Function to convert Google Drive URL to shareable view URL
const getDirectImageUrl = (driveUrl) => {
  if (
    !driveUrl ||
    driveUrl === "No photo" ||
    driveUrl === "Error storing photo"
  ) {
    return null;
  }

  // If it's already a shareable view URL, return as is
  if (driveUrl.includes("/file/d/") && driveUrl.includes("/view")) {
    return driveUrl;
  }

  // Convert Google Drive file URL to shareable view URL
  if (driveUrl.includes("drive.google.com/file/d/")) {
    const fileId = driveUrl.match(/\/file\/d\/([^\/]+)/)?.[1];
    if (fileId) {
      return `https://drive.google.com/file/d/${fileId}/view?usp=drive_link`;
    }
  }

  // If it's a direct download URL, convert to shareable view URL
  if (driveUrl.includes("uc?id=") || driveUrl.includes("export=download")) {
    const fileId = driveUrl.match(/[?&]id=([^&]+)/)?.[1];
    if (fileId) {
      return `https://drive.google.com/file/d/${fileId}/view?usp=drive_link`;
    }
  }

  // If it's just a file ID, create shareable URL
  if (driveUrl.match(/^[a-zA-Z0-9_-]{20,}$/)) {
    return `https://drive.google.com/file/d/${driveUrl}/view?usp=drive_link`;
  }

  return driveUrl;
};

  const handleImageError = (event) => {
    console.error("Image failed to load:", event.target.src);
    event.target.style.display = "none";
  };

  // Check review existence
  useEffect(() => {
    if (user?.email) {
      checkUserReview(user.email);
    }
  }, [user]);

  const handleDrawerToggle = () => {
    setDrawerOpen(!drawerOpen);
  };

  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
  };

  const handleMobileMenuItemClick = (href) => {
    // Close drawer first
    setDrawerOpen(false);

    // Wait a bit for drawer to close then scroll
    setTimeout(() => {
      const element = document.querySelector(href);
      if (element) {
        element.scrollIntoView({ behavior: "smooth" });
      }
    }, 100);
  };

  const handleDesktopTabClick = (href, index) => {
    setCurrentTab(index);
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: "smooth" });
    }
  };

  const handleAddReviewClick = async () => {
    if (user?.email) {
      setCheckingReview(true);
      try {
        const data = await checkUserReview(user.email);
        if (data.hasReview) {
          setHasReviewed(true);
          showFeedbackDialog("Your review has already been shared.", "info");
          setReviewDialogOpen(false);
        } else {
          setHasReviewed(false);
          setReviewDialogOpen(true);
        }
      } catch (error) {
        console.error("Error checking review:", error);
        setHasReviewed(false);
        setReviewDialogOpen(true);
      } finally {
        setCheckingReview(false);
      }
    } else {
      setAuthDialogOpen(true);
    }
  };

  // Check if user has already reviewed
  const checkUserReview = async (email) => {
    try {
      const params = new URLSearchParams({
        action: "check",
        email: email,
      });
      const url = `${GOOGLE_SCRIPT_URL}?${params.toString()}`;

      const response = await fetch(url);
      const data = await response.json();
      return data; // contains { hasReview: true/false, message }
    } catch (error) {
      console.error("Error checking review:", error);
      return { hasReview: false };
    }
  };

  // Google OAuth Success
  const handleGoogleSuccess = async (credentialResponse) => {
    setGoogleAuthLoading(true);
    try {
      const decoded = jwtDecode(credentialResponse.credential);
      setUser({
        ...decoded,
        picture: decoded.picture, // This contains the Google profile photo URL
      });
      setReviewData((prev) => ({
        ...prev,
        name: decoded.name || "",
        photo: decoded.picture, // Set the Google profile photo URL as the photo
      }));
      setAuthDialogOpen(false);

      setCheckingReview(true);
      const reviewCheck = await checkUserReview(decoded.email);
      if (reviewCheck.hasReview) {
        setHasReviewed(true);
        setReviewDialogOpen(false);
        showFeedbackDialog("Your review has already been shared.", "info");
      } else {
        setHasReviewed(false);
        setReviewDialogOpen(true);
      }
    } catch (error) {
      console.error("Google auth error:", error);
      showFeedbackDialog("Authentication failed. Please try again.", "error");
    } finally {
      setGoogleAuthLoading(false);
      setCheckingReview(false);
    }
  };

  const handleGoogleError = () => {
    showFeedbackDialog(
      "Google authentication failed. Please try again.",
      "error"
    );
  };

  const handleAuthDialogClose = () => {
    setAuthDialogOpen(false);
  };

  const handleReviewDialogClose = () => {
    setReviewDialogOpen(false);
    setReviewData({
      name: user ? user.name || "" : "",
      rating: 0,
      comment: "",
    });
    setAddPhotos([]);
    setAddPhotosPreview([]);
  };

  // const handlePhotoUpload = (event) => {
  //   const file = event.target.files[0];
  //   if (file) {
  //     if (!file.type.startsWith("image/")) {
  //       showFeedbackDialog("Please upload an image file", "error");
  //       return;
  //     }
  //     if (file.size > 5 * 1024 * 1024) {
  //       showFeedbackDialog("Please upload an image smaller than 5MB", "error");
  //       return;
  //     }

  //     setPhotoUploading(true);
  //     const reader = new FileReader();
  //     reader.onload = (e) => {
  //       setReviewData((prev) => ({
  //         ...prev,
  //         photo: file,
  //         photoPreview: e.target.result,
  //       }));
  //       setPhotoUploading(false);
  //     };
  //     reader.onerror = () => {
  //       showFeedbackDialog("Failed to upload photo", "error");
  //       setPhotoUploading(false);
  //     };
  //     reader.readAsDataURL(file);
  //   }
  // };

  // const handleRemovePhoto = () => {
  //   setReviewData((prev) => ({ ...prev, photo: null, photoPreview: null }));
  // };

  const handleAddPhotosUpload = (event) => {
    const files = Array.from(event.target.files);
    const validFiles = files.filter(
      (file) =>
        file.type.startsWith("image/") &&
        file.size <= 5 * 1024 * 1024 &&
        !addPhotos.find((f) => f.name === file.name)
    );

    if (validFiles.length < files.length) {
      showFeedbackDialog(
        "Some files were not images or were over 5MB.",
        "warning"
      );
    }

    setAdditionalPhotosUploading(true);
    setAddPhotos((prev) => [...prev, ...validFiles]);

    let processedCount = 0;
    const newPreviews = [];

    validFiles.forEach((file, index) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        newPreviews.push(e.target.result);
        processedCount++;

        if (processedCount === validFiles.length) {
          setAddPhotosPreview((prev) => [...prev, ...newPreviews]);
          setAdditionalPhotosUploading(false);
        }
      };
      reader.onerror = () => {
        processedCount++;
        if (processedCount === validFiles.length) {
          setAdditionalPhotosUploading(false);
        }
      };
      reader.readAsDataURL(file);
    });

    if (validFiles.length === 0) {
      setAdditionalPhotosUploading(false);
    }
  };

  const handleRemoveAddPhoto = (index) => {
    setAddPhotos((prev) => prev.filter((_, i) => i !== index));
    setAddPhotosPreview((prev) => prev.filter((_, i) => i !== index));
  };

  const showFeedbackDialog = (message, severity = "success") => {
    setFeedbackDialog({ open: true, message, severity });
  };

  const handleFeedbackDialogClose = () => {
    setFeedbackDialog((prev) => ({ ...prev, open: false }));
  };

  const handleInputChange = (field, value) => {
    setReviewData((prev) => ({ ...prev, [field]: value }));
  };

  // Submit Review Function

const handleReviewSubmit = async () => {
  // Validation - Make photo and comment mandatory
  if (reviewData.rating === 0) {
    showFeedbackDialog("Please provide a rating", "error");
    return;
  }

  if (!reviewData.comment.trim()) {
    showFeedbackDialog("Please provide a review comment", "error");
    return;
  }

  setLoading(true);

  // Define payload outside try block so it's accessible in catch
  let payload;

  try {
    // Convert additional photos to base64 for upload
    const additionalPhotosBase64 = 
      addPhotos.length > 0 ? await filesToBase64Array(addPhotos) : [];
    
    // Construct payload
    payload = {
      name: reviewData.name.trim(),
      email: user?.email || "unknown@example.com",
      rating: reviewData.rating,
      comment: reviewData.comment?.trim() || "",
      photo: user?.picture || "No photo",
      additionalPhotos: additionalPhotosBase64,
      action: "submitReview",
      returnShareableUrls: true // Ensure this flag is set
    };

  

    // Send the request
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: "POST",
      headers: { 
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify(payload),
    });


    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();

    if (data.success) {
      showFeedbackDialog("Thank you! Your review was submitted.", "success");
      handleReviewDialogClose();
      setHasReviewed(true);
      
      // Log the returned URLs for debugging
      if (data.testimonial) {
     
      }
    } else {
      throw new Error(data.message || "Submission failed");
    }
  } catch (error) {
    console.error("Review submission error:", error);
    
    // For CORS issues, try with no-cors as fallback
    if (error.message.includes("Failed to fetch") || error.message.includes("CORS")) {
      
      try {
        // Fallback: try with no-cors mode
        await fetch(GOOGLE_SCRIPT_URL, {
          method: "POST",
          mode: "no-cors",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ...payload,
            action: "submitReview",
            returnShareableUrls: true
          }),
        });

        // Assume success for no-cors requests
        showFeedbackDialog("Thank you! Your review was submitted.", "success");
        handleReviewDialogClose();
        setHasReviewed(true);
      } catch (fallbackError) {
        console.error("Fallback submission error:", fallbackError);
        showFeedbackDialog("Submission failed. Try again later.", "error");
      }
    } else {
      showFeedbackDialog("Submission failed. Try again later.", "error");
    }
  } finally {
    setLoading(false);
  }
};
  const drawerContent = (
    <Box
      sx={{
        width: 280,
        height: "100%",
        background:
          "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        padding: 2,
      }}
    >
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <FaTableTennis className="text-orange-500 text-2xl" />
          <span className="font-in font-bold text-white">BT's TT Academy</span>
        </Box>
        <IconButton onClick={handleDrawerToggle} sx={{ color: "white" }}>
          <Close />
        </IconButton>
      </Box>
      <List>
        {menuItems.map((item, index) => (
          <ListItem
            key={item.label}
            button
            onClick={() => handleMobileMenuItemClick(item.href)}
            sx={{
              border:
                currentTab === index
                  ? "1px solid #FF9800"
                  : "1px solid rgba(255,255,255,0.1)",
              borderRadius: "8px",
              marginBottom: 1,
              background:
                currentTab === index
                  ? "rgba(255,165,0,0.2)"
                  : "rgba(255,255,255,0.05)",
              textDecoration: "none",
              color: "inherit",
            }}
          >
            <ListItemText
              primary={item.label}
              sx={{
                color: currentTab === index ? "#FF9800" : "white",
                "& .MuiListItemText-primary": {
                  fontFamily: "'AlanSans', sans-serif",
                  fontWeight: currentTab === index ? 600 : 500,
                },
              }}
            />
          </ListItem>
        ))}
      </List>
      <Box sx={{ padding: 2 }}>
        <CustomButton
          rating
          size="small"
          onClick={handleAddReviewClick}
          fullWidth
          text={checkingReview ? "Checking..." : "Add Review"}
          disabled={checkingReview}
        />
      </Box>
    </Box>
  );

  return (
    <>
      <AppBar
        position="static"
        sx={{
          background: "transparent",
          boxShadow: "none",
        }}
      >
        <Toolbar sx={{ justifyContent: "space-between", padding: "8px 0" }}>
          <Box sx={{ display: "flex", alignItems: "center" }}>
            {/* <FaTableTennis className="text-white text-3xl" /> */}
            <img src={colorLogo} className=" w-16" />
          </Box>
          <Box
            sx={{
              display: { xs: "none", md: "flex" },
              alignItems: "center",
              gap: 2,
            }}
          >
            <Box
              sx={{
                background: "rgba(0,0,0,0.1)",
                borderRadius: "25px",
                border: "1px solid rgba(255,255,255,0.1)",
                padding: "4px",
              }}
            >
              <Tabs
                value={currentTab}
                onChange={handleTabChange}
                sx={{
                  minHeight: "40px",
                  "& .MuiTabs-indicator": {
                    backgroundColor: "#f97316",
                    height: "100%",
                    borderRadius: "25px",
                  },
                  "& .MuiTab-root": {
                    color: "rgba(255,255,255,0.7)",
                    fontFamily: "'AlanSans', sans-serif",
                    fontWeight: 500,
                    fontSize: "14px",
                    textTransform: "none",
                    minHeight: "32px",
                    margin: "0 2px",
                    minWidth: "auto",
                    zIndex: 1,
                    "&.Mui-selected": {
                      color: "white",
                      fontWeight: 600,
                    },
                    "&:hover": {
                      color: "#E2DBD1",
                    },
                  },
                }}
              >
                {menuItems.map((item, index) => (
                  <Tab
                    key={item.label}
                    label={item.label}
                    onClick={() => handleDesktopTabClick(item.href, index)}
                  />
                ))}
              </Tabs>
            </Box>
            <CustomButton
              rating
              size="small"
              text={checkingReview ? "Checking..." : "Add Review"}
              onClick={handleAddReviewClick}
              disabled={checkingReview}
            />
          </Box>
          <IconButton
            sx={{
              display: { xs: "flex", md: "none" },
              color: "white",
              background: "rgba(0,0,0,0.1)",
              border: "1px solid rgba(255,255,255,0.1)",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
              },
            }}
            onClick={handleDrawerToggle}
          >
            <GiHamburgerMenu />
          </IconButton>
        </Toolbar>
      </AppBar>

      <Drawer
        variant="temporary"
        anchor="right"
        open={drawerOpen}
        onClose={handleDrawerToggle}
        ModalProps={{ keepMounted: true }}
        sx={{
          display: { xs: "block", md: "none" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: 280,
            border: "none",
            background: "transparent",
          },
        }}
      >
        {drawerContent}
      </Drawer>

      {/* Auth Dialog */}
      <Dialog
        open={authDialogOpen}
        onClose={handleAuthDialogClose}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
            textAlign: "center",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography
            variant="h6"
            sx={{ fontFamily: "'AlanSans', sans-serif" }}
          >
            Sign In to Continue
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ padding: 3 }}>
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
            }}
          >
            <FaTableTennis className="text-orange-500 text-4xl" />
            <Typography
              variant="h6"
              sx={{ fontFamily: "'AlanSans', sans-serif" }}
            >
              BT's TT Academy
            </Typography>
            <Typography
              variant="body2"
              sx={{ color: "rgba(255,255,255,0.7)", mb: 2 }}
            >
              Sign in with Google to add your review and share your experience
              with our academy.
            </Typography>
            {googleAuthLoading ? (
              <Box
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: 2,
                }}
              >
                <CircularProgress size={30} sx={{ color: "#FF9800" }} />
                <Typography
                  variant="body2"
                  sx={{ color: "rgba(255,255,255,0.7)" }}
                >
                  Authenticating...
                </Typography>
              </Box>
            ) : (
              <Box sx={{ width: "100%", maxWidth: "200px" }}>
                <GoogleLogin
                  onSuccess={handleGoogleSuccess}
                  onError={handleGoogleError}
                  size="large"
                  width="100%"
                  shape="circle"
                />
              </Box>
            )}
          </Box>
        </DialogContent>
        <DialogActions
          sx={{
            padding: 2,
            justifyContent: "center",
            borderTop: "1px solid rgba(255,255,255,0.1)",
          }}
        >
          <Button
            onClick={handleAuthDialogClose}
            disabled={googleAuthLoading}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover:not(:disabled)": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
        </DialogActions>
      </Dialog>

      {/* Review Dialog */}
      <Dialog
        open={reviewDialogOpen}
        onClose={handleReviewDialogClose}
        maxWidth="sm"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography
            variant="h6"
            sx={{ fontFamily: "'AlanSans', sans-serif" }}
          >
            Add Your Review
          </Typography>
          {user && (
            <Typography
              variant="body2"
              sx={{ color: "rgba(255,255,255,0.7)", mt: 0.5 }}
            >
              Signed in as: {user.name || user.email}
            </Typography>
          )}
        </DialogTitle>
        <DialogContent sx={{ padding: 3 }}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            {/* Name Field */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Name *
              </Typography>
              <TextField
                fullWidth
                value={reviewData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                placeholder="Enter your name"
                variant="outlined"
                disabled={!!user}
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: user
                        ? "rgba(255,255,255,0.2)"
                        : "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                    "& .MuiInputBase-input.Mui-disabled": {
                      WebkitTextFillColor: "rgba(255,255,255,0.7)",
                    },
                  },
                }}
              />
              {user && (
                <Typography
                  variant="caption"
                  sx={{
                    color: "rgba(255,255,255,0.5)",
                    mt: 1,
                    display: "block",
                  }}
                >
                  Name is taken from your Google profile
                </Typography>
              )}
            </Box>

            {/* Avatar Photo Upload - Now Mandatory */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Photo (Avatar) *
              </Typography>
              {user?.picture ? (
                <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                  <Avatar
                    src={user.picture}
                    sx={{ width: 80, height: 80, border: "2px solid #FF9800" }}
                  />
                  <Box>
                    <Chip
                      label="Google Profile Photo"
                      variant="outlined"
                      sx={{
                        color: "white",
                        borderColor: "rgba(255,255,255,0.3)",
                      }}
                    />
                    <Typography
                      variant="caption"
                      sx={{
                        color: "rgba(255,255,255,0.5)",
                        display: "block",
                        mt: 1,
                      }}
                    >
                      Photo from your Google account
                    </Typography>
                  </Box>
                </Box>
              ) : (
                <Typography
                  variant="body2"
                  sx={{ color: "rgba(255,255,255,0.7)", fontStyle: "italic" }}
                >
                  Your Google profile photo will be used
                </Typography>
              )}
            </Box>

            {/* Add Photos Multiple - Optional */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Add Photos (Optional, Multiple)
              </Typography>
              <input
                multiple
                type="file"
                accept="image/*"
                style={{ display: "none" }}
                ref={addPhotosInputRef}
                onChange={handleAddPhotosUpload}
              />
              {additionalPhotosUploading ? (
                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 2,
                    padding: 2,
                    marginBottom: 2,
                  }}
                >
                  <CircularProgress size={24} sx={{ color: "#FF9800" }} />
                  <Typography
                    variant="body2"
                    sx={{ color: "rgba(255,255,255,0.7)" }}
                  >
                    Uploading photos...
                  </Typography>
                </Box>
              ) : (
                <Box
                  sx={{
                    border: "2px dashed rgba(255,255,255,0.3)",
                    borderRadius: "8px",
                    padding: 3,
                    textAlign: "center",
                    cursor: "pointer",
                    minHeight: "60px",
                    "&:hover": {
                      borderColor: "#FF9800",
                      background: "rgba(255,152,0,0.05)",
                    },
                    marginBottom: 2,
                  }}
                  onClick={() => addPhotosInputRef.current.click()}
                >
                  <FaCloudUploadAlt
                    style={{ fontSize: "2rem", color: "#FF9800" }}
                  />
                  <Typography
                    variant="body2"
                    sx={{ color: "rgba(255,255,255,0.7)" }}
                  >
                    Click to upload extra photos
                  </Typography>
                  <Typography
                    variant="caption"
                    sx={{ color: "rgba(255,255,255,0.5)" }}
                  >
                    PNG, JPG, JPEG (Max 5MB each)
                  </Typography>
                </Box>
              )}
              <Grid container spacing={2}>
                {addPhotosPreview.map((preview, idx) => (
                  <Grid item key={idx}>
                    <Box
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                      }}
                    >
                      <Avatar
                        src={preview}
                        sx={{
                          width: 60,
                          height: 60,
                          border: "2px solid #FF9800",
                          marginBottom: 1,
                        }}
                      />
                      <Chip
                        label={addPhotos[idx]?.name || ""}
                        variant="outlined"
                        sx={{
                          color: "white",
                          borderColor: "rgba(255,255,255,0.3)",
                          marginBottom: 1,
                        }}
                      />
                      <IconButton
                        sx={{ color: "#FF9800" }}
                        onClick={() => handleRemoveAddPhoto(idx)}
                      >
                        <Delete />
                      </IconButton>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Box>

            {/* Rating */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Rating *
              </Typography>
              <Rating
                value={reviewData.rating}
                onChange={(e, newValue) =>
                  handleInputChange("rating", newValue)
                }
                size="large"
                sx={{
                  color: "#FF9800",
                  "& .MuiRating-iconEmpty": {
                    color: "white", // White color for unselected stars
                  },
                  "& .MuiRating-iconFilled": {
                    color: "#FF9800",
                  },
                }}
              />
            </Box>

            {/* Comment - Now Mandatory */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Review *
              </Typography>
              <TextField
                multiline
                rows={4}
                fullWidth
                value={reviewData.comment}
                onChange={(e) => handleInputChange("comment", e.target.value)}
                placeholder="Share your experience with BT's TT Academy... (Required)"
                variant="outlined"
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": { borderColor: "rgba(255,255,255,0.2)" },
                    "&:hover fieldset": {
                      borderColor: "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": { borderColor: "#FF9800" },
                  },
                }}
              />
            </Box>
          </Box>
        </DialogContent>
        <DialogActions
          sx={{ padding: 3, borderTop: "1px solid rgba(255,255,255,0.1)" }}
        >
          <Button
            onClick={handleReviewDialogClose}
            disabled={loading}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover:not(:disabled)": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleReviewSubmit}
            variant="contained"
            disabled={
  !reviewData.name.trim() ||
  reviewData.rating === 0 ||
  loading ||
  hasReviewed ||
  !reviewData.comment.trim()
}
            sx={{
              background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
              "&:hover:not(:disabled)": {
                background: "linear-gradient(45deg, #E65100 30%, #BF360C 90%)",
              },
              "&:disabled": {
                background: "rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.3)",
              },
              minWidth: "120px",
            }}
          >
            {loading ? (
              <CircularProgress size={24} sx={{ color: "white" }} />
            ) : (
              "Submit Review"
            )}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Feedback Dialog */}
      <Dialog
        open={feedbackDialog.open}
        onClose={handleFeedbackDialogClose}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
            textAlign: "center",
            padding: 2,
          },
        }}
      >
        <DialogTitle>
          <Typography
            variant="h6"
            sx={{
              color:
                feedbackDialog.severity === "error"
                  ? "#FF5252"
                  : feedbackDialog.severity === "success"
                  ? "#4CAF50"
                  : feedbackDialog.severity === "info"
                  ? "#FF9800"
                  : "#FFC107",
              mb: 1,
            }}
          >
            {feedbackDialog.severity.charAt(0).toUpperCase() +
              feedbackDialog.severity.slice(1)}
          </Typography>
        </DialogTitle>
        <DialogContent>
          <Typography variant="body1">{feedbackDialog.message}</Typography>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleFeedbackDialogClose}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default NavBar;
